import { copyFileSync, existsSync, rmSync } from "node:fs";
import { execFile } from "node:child_process";
import { join } from "node:path";
import { promisify } from "node:util";
import { resolveTarget, stateFile, resolveAsset } from "../lib/paths.js";
import { logger } from "../lib/logger.js";
import { diffTree, type PkgInclude, type DiffPlan } from "../lib/diff.js";
import { createBackup } from "../lib/backup.js";
import {
  readAssetsVersion,
  readCliVersion,
  writeState,
  requireState,
  compareVersions,
  StateMissingError,
  type InstallState,
  type ChannelKey,
} from "../lib/version.js";
import { installCodegraph, installEntire } from "../lib/plugins/index.js";
import { copyDir } from "../lib/copy.js";
import { selfUpdate } from "../upgrade/self.js";
import type { Channels } from "../lib/ui.js";

const execFileAsync = promisify(execFile);

const NPM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes — codegraph npm install can be slow
const EXEC_MAX_BUFFER = 64 * 1024 * 1024; // 64MB

export interface UpgradeOptions {
  target?: string;
  /** When true, delete files in target that are no longer in assets. */
  prune?: boolean;
  dryRun?: boolean;
  /** Skip the CLI self-update stage entirely. */
  noSelf?: boolean;
  with?: string;
  without?: string;
  /** Reserved for symmetry with install; upgrade has no interactive prompts today. */
  yes?: boolean;
}

/**
 * `pisquad upgrade` — sync a target install with the assets bundled in this
 * CLI package. See `docs/tasks/pisquad-cli/11-upgrade-command.md` for the full
 * behavioural contract.
 */
export async function upgradeCommand(options: UpgradeOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const dryRun = options.dryRun === true;
  logger.info(`pisquad upgrade → ${target}${dryRun ? " (dry-run)" : ""}`);

  // 1. CLI self-update — if we actually upgraded the global CLI, the in-memory
  //    code is stale; tell the user to re-run and exit cleanly.
  let selfResult;
  try {
    selfResult = await selfUpdate({ logger, noSelf: options.noSelf });
  } catch (error) {
    logger.error(
      `CLI self-update failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
    return;
  }
  if (selfResult.updated) {
    logger.success(
      "CLI self-updated to latest. Re-run `pisquad upgrade` to sync this project with the new version.",
    );
    return;
  }

  // 2. Require an existing install — legacy bash-installed projects have no
  //    state.json and must reinstall (PRD non-goal #1).
  let state: InstallState;
  try {
    state = requireState(target);
  } catch (error) {
    if (error instanceof StateMissingError) {
      logger.error(error.message);
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  // 3. Decide the post-upgrade channel set: state baseline + flags.
  let newChannels;
  try {
    newChannels = mergeChannels(state.channels, options);
  } catch (error) {
    logger.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
    return;
  }
  const cliVersion = readCliVersion();
  const assetsVersion = readAssetsVersion();
  const versionDiff = compareVersions(state, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
  });

  // 4. Build the diff include list (subtree granularity, never the whole .pi/).
  //    The includes are intentionally narrow so .pi/assets-version.txt and
  //    .pi/.gitignore (root files) never enter the diff.
  const includes: PkgInclude[] = [
    { pkgSubPath: ".pi/agents", targetSubPath: ".pi/agents" },
    { pkgSubPath: ".pi/skills", targetSubPath: ".pi/skills" },
    {
      pkgSubPath: ".pi/extensions/subagent",
      targetSubPath: ".pi/extensions/subagent",
    },
    {
      pkgSubPath: ".pi/extensions/wikilink-lint",
      targetSubPath: ".pi/extensions/wikilink-lint",
    },
    { pkgSubPath: "docs", targetSubPath: "docs" },
  ];
  if (newChannels.codegraph) {
    includes.push({
      pkgSubPath: ".pi/extensions/codegraph",
      targetSubPath: ".pi/extensions/codegraph",
    });
  }
  if (newChannels.entire) {
    includes.push({
      pkgSubPath: ".pi/extensions/entire",
      targetSubPath: ".pi/extensions/entire",
    });
  }

  // 5. Compute the diff plan.
  const plan = await diffTree(target, includes);

  if (versionDiff.versionChanged) {
    logger.info(`assets version: ${state.version} → ${assetsVersion}`);
  }
  if (versionDiff.cliVersionChanged) {
    logger.info(`CLI version: ${state.cliVersion} → ${cliVersion}`);
  }
  if (versionDiff.newChannels.length > 0) {
    logger.info(`new channels: ${versionDiff.newChannels.join(", ")}`);
  }
  if (versionDiff.removedChannels.length > 0) {
    logger.info(`removed channels: ${versionDiff.removedChannels.join(", ")}`);
  }

  // 6. Dry-run: print the plan and stop before any writes.
  if (dryRun) {
    printPlan(plan, options.prune === true);
    logger.info("DRY RUN — no changes made");
    return;
  }

  // 7. Back up files that will be overwritten (and, when pruning, deleted).
  const backupSet = new Set<string>();
  for (const m of plan.modified) backupSet.add(m.relPath);
  if (options.prune) {
    for (const r of plan.removed) backupSet.add(r.relPath);
  }
  if (backupSet.size > 0) {
    await createBackup(target, Array.from(backupSet).map((relPath) => ({ relPath })), "before-upgrade");
  }

  // 8-11. Apply changes, prune, run channel-specific work. Wrapped so any
  //       failure is surfaced cleanly with exit code 1 and the backup tarball
  //       left on disk for the user to inspect / restore manually.
  try {
    // 8. Apply modified + added by syncing each include subtree from assets.
    //    copyDir overwrites only files present in src, leaving extra files in
    //    dest alone — so user-added files survive unless --prune handles them
    //    explicitly below.
    for (const inc of includes) {
      const source = resolveAsset(inc.pkgSubPath);
      const destination = join(target, inc.targetSubPath);
      const isCodegraph = inc.pkgSubPath === ".pi/extensions/codegraph";
      copyDir(source, destination, {
        filter: isCodegraph
          ? (_abs, rel) => rel !== "node_modules" && rel !== "package-lock.json"
          : undefined,
        onSkip: (rel, reason) => logger.warn(`Skipped ${rel} (${reason})`),
      });
    }

    // 9. Handle removed files: default keep, --prune delete.
    if (options.prune) {
      for (const r of plan.removed) {
        const abs = join(target, r.relPath);
        try {
          rmSync(abs, { force: true });
        } catch (error) {
          logger.warn(
            `Failed to prune ${r.relPath}: ${error instanceof Error ? error.message : String(error)}`,
          );
        }
      }
    }

    // 10. Channel-specific handling.
    const codegraphNewlyEnabled = newChannels.codegraph && !state.channels.codegraph;
    const entireNewlyEnabled = newChannels.entire && !state.channels.entire;

    if (codegraphNewlyEnabled) {
      // installCodegraph does its own copy + npm install + codegraph init.
      // The copy we did in step 8 is redundant but harmless (writes the same
      // content) — we let installCodegraph own the full bootstrap.
      await installCodegraph(target, { logger });
    } else if (newChannels.codegraph) {
      // Already enabled. Re-run npm install only when the extension payload
      // actually changed (package.json etc.). Never re-run codegraph init —
      // the user's index lives there.
      const codegraphChanged =
        plan.modified.some((p) => p.relPath.startsWith(".pi/extensions/codegraph/")) ||
        plan.added.some((p) => p.relPath.startsWith(".pi/extensions/codegraph/"));
      if (codegraphChanged) {
        await runNpmInstall(join(target, ".pi", "extensions", "codegraph"));
      }
    }

    if (entireNewlyEnabled) {
      await installEntire(target, { logger });
    }

    // 11. codegraph.json: only copy when the target lacks one. We never
    //     overwrite the user's existing config (respect their customisation).
    //     When codegraph is newly enabled, installCodegraph already handles
    //     this; we only need to run the check for the pre-existing case.
    if (newChannels.codegraph && !codegraphNewlyEnabled) {
      const configDest = join(target, "codegraph.json");
      if (!existsSync(configDest)) {
        const configSource = resolveAsset("codegraph.json");
        if (existsSync(configSource)) {
          copyFileSync(configSource, configDest);
          logger.info(`copied codegraph.json → ${configDest}`);
        }
      } else {
        logger.info("codegraph.json already present, keeping user copy");
      }
    }
  } catch (error) {
    logger.error(`upgrade failed: ${error instanceof Error ? error.message : String(error)}`);
    if (backupSet.size > 0) {
      logger.error(`backup retained on disk under .pi/.pisquad/backups/ for manual restore`);
    }
    process.exitCode = 1;
    return;
  }

  // 12. Persist new state.
  writeState(target, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
    lastUpgradedAt: new Date().toISOString(),
  });

  // 13. Summary.
  printSummary({
    newChannels,
    backupCount: backupSet.size,
    backupPaths: [],
    removedCount: plan.removed.length,
    pruned: options.prune === true,
    statePath: stateFile(target),
    modifiedCount: plan.modified.length,
    addedCount: plan.added.length,
  });
}

async function runNpmInstall(cwd: string): Promise<void> {
  try {
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: EXEC_MAX_BUFFER,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`npm install in ${cwd} failed: ${message}`);
  }
}

function printPlan(plan: DiffPlan, prune: boolean): void {
  logger.info(`modified (${plan.modified.length}):`);
  for (const m of plan.modified) logger.info(`  M ${m.relPath}`);
  logger.info(`added (${plan.added.length}):`);
  for (const a of plan.added) logger.info(`  A ${a.relPath}`);
  logger.info(`removed (${plan.removed.length}):`);
  for (const r of plan.removed) logger.info(`  D ${r.relPath}${prune ? " (will delete)" : " (will keep)"}`);
  logger.info(`unchanged (${plan.unchanged.length})`);
  if (prune && plan.removed.length > 0) {
    logger.info(`Pruning will also back up the ${plan.removed.length} removed file(s) before deletion.`);
  }
}

interface Summary {
  newChannels: Channels;
  backupCount: number;
  backupPaths: string[];
  removedCount: number;
  pruned: boolean;
  statePath: string;
  modifiedCount: number;
  addedCount: number;
}

function printSummary(s: Summary): void {
  const parts = ["core"];
  if (s.newChannels.codegraph) parts.push("codegraph");
  if (s.newChannels.entire) parts.push("entire");
  logger.info(`Channels: ${parts.join(" + ")}`);
  logger.info(`Modified: ${s.modifiedCount}, added: ${s.addedCount}`);
  if (s.removedCount > 0) {
    if (s.pruned) {
      logger.info(`Removed: ${s.removedCount} (pruned)`);
    } else {
      logger.info(`Removed: ${s.removedCount} (kept — pass --prune to delete)`);
    }
  }
  if (s.backupCount > 0) {
    logger.info(`Backup: ${s.backupCount} file(s) archived`);
  }
  logger.info(`State: ${s.statePath}`);
  logger.success("upgrade complete");
}

// ---- channel merging ---------------------------------------------------------

function parseChannelList(input: string | undefined): Set<Exclude<ChannelKey, "core">> {
  const out = new Set<Exclude<ChannelKey, "core">>();
  if (!input) return out;
  for (const raw of input.split(",")) {
    const v = raw.trim().toLowerCase();
    if (!v) continue;
    if (v === "codegraph" || v === "entire") out.add(v);
    else if (v !== "core") throw new Error(`Unknown channel: ${v}`);
  }
  return out;
}

/**
 * Merge `--with` / `--without` flags onto the state's existing channel set.
 *
 *   - state.channels is the baseline (no implicit changes).
 *   - `--with X` adds X to the baseline (idempotent).
 *   - `--without X` removes X from the baseline (idempotent).
 *   - `--with` and `--without` are mutually exclusive.
 *
 * `core` is always `true`; the schema pins it. The task spec uses this same
 * merge order so a later `pisquad upgrade --with codegraph` after a core-only
 * install adds the channel without re-prompting.
 */
function mergeChannels(base: Channels, options: { with?: string; without?: string }): Channels {
  const withSet = parseChannelList(options.with);
  const withoutSet = parseChannelList(options.without);
  if (withSet.size > 0 && withoutSet.size > 0) {
    throw new Error("Cannot combine --with and --without");
  }
  const next: Channels = {
    core: true,
    codegraph: base.codegraph,
    entire: base.entire,
  };
  if (withSet.size > 0) {
    for (const k of withSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = true;
  }
  if (withoutSet.size > 0) {
    for (const k of withoutSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = false;
  }
  return next;
}

import { spawn } from "node:child_process";
import { logger as defaultLogger } from "../lib/logger.js";
import { execCapture as defaultExecCapture, which as defaultWhich, type ExecCaptureResult } from "../lib/env.js";
import { readCliVersion } from "../lib/version.js";
import type { Logger } from "../lib/plugins/types.js";

/**
 * CLI self-update stage of `pisquad upgrade`.
 *
 * The contract is:
 *
 *   - Honor `--no-self` (CLI flag) or `PISQUAD_NO_SELF=1` (env): when set,
 *     skip the entire stage and report `updated: false`.
 *   - Only attempt an update when the `pisquad` binary on PATH resolves to a
 *     file under npm's global prefix (i.e. was installed via `npm i -g`). When
 *     the binary is missing, or is a non-global install (e.g. `npx @nicklin/pisquad@latest`
 *     sandbox or local dev tree), print "CLI not from global npm, skipping
 *     self-update" and return.
 *   - When the install is confirmed global, compare the version embedded in
 *     this CLI's `package.json` against the latest version on the npm
 *     registry. Skip the reinstall (return `updated: false`, reason
 *     `"already latest"`) when they match — this prevents the
 *     `upgrade → re-run → upgrade` loop that an unconditional
 *     `npm install -g @nicklin/pisquad@latest` would create, since npm
 *     considers itself successful even when there is nothing to install.
 *   - When the registry version differs, run `npm install -g
 *     @nicklin/pisquad@latest` and, on success, return `updated: true` so the
 *     upgrade command can prompt the user to re-run with the new binary.
 *   - When the registry call itself fails (offline, non-zero exit), skip the
 *     self-update with a warning and return `updated: false`, reason
 *     `"npm view failed"` — we deliberately do not reinstall on an unknown
 *     remote state.
 *   - On `npm install -g` failure, throw — the upgrade command aborts
 *     without touching the target project.
 *
 * The `deps` hook is for tests only: callers should not pass it in production.
 */

export interface SelfUpdateDeps {
  which?: (cmd: string) => string | null;
  execCapture?: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>;
  /**
   * Override the actual `npm install -g` runner. The default spawns npm with
   * a 2-minute timeout; tests inject a stub that returns a synthetic
   * ExecCaptureResult so no real npm process is ever spawned.
   */
  runNpmInstallGlobal?: () => Promise<ExecCaptureResult>;
}

export interface SelfUpdateOptions {
  logger?: Logger;
  /** Honor the CLI's `--no-self` flag. */
  noSelf?: boolean;
  /** @internal Test seam — override `which` / `execCapture`. */
  deps?: SelfUpdateDeps;
}

export interface SelfUpdateResult {
  updated: boolean;
  /** Human-readable reason for the skip / failure (diagnostic only). */
  reason?: string;
}

const NPM_TIMEOUT_MS = 2 * 60 * 1000; // 2 minutes — global installs are usually fast
const NPM_GLOBAL_ARGS = ["install", "-g", "@nicklin/pisquad@latest", "--no-audit", "--no-fund"];

/**
 * Spawn `npm install -g @nicklin/pisquad@latest` with a hard timeout.
 *
 * `execCapture` in env.ts does not enforce a timeout, and a stuck global
 * install would otherwise block the whole upgrade command. We use a dedicated
 * spawn here so the timeout is scoped to this stage only.
 */
function runNpmInstallGlobal(): Promise<ExecCaptureResult> {
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    let settled = false;

    let child: ReturnType<typeof spawn>;
    try {
      child = spawn("npm", NPM_GLOBAL_ARGS, { stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      reject(new Error(`failed to spawn npm: ${message}`));
      return;
    }

    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill("SIGTERM");
      reject(new Error(`npm install -g @nicklin/pisquad@latest timed out after ${NPM_TIMEOUT_MS / 1000}s`));
    }, NPM_TIMEOUT_MS);

    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");
    child.stdout?.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr?.on("data", (chunk: string) => {
      stderr += chunk;
    });
    child.on("error", (error) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      reject(error);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      resolve({ stdout, stderr, exitCode: code ?? 1 });
    });
  });
}

/**
 * Ask npm for the latest published version of `@nicklin/pisquad`. Returns
 * the trimmed version string on success, or `null` when the registry call
 * failed (offline, non-zero exit, or empty stdout). The caller is expected
 * to treat a `null` result as "could not determine latest version" and skip
 * the self-update with a warning rather than risk an unconditional reinstall.
 */
async function getLatestVersion(
  execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>,
): Promise<string | null> {
  const result = await execCapture("npm", ["view", "@nicklin/pisquad", "version"]);
  if (result.exitCode !== 0) return null;
  const version = result.stdout.trim();
  return version.length > 0 ? version : null;
}

/**
 * Ask npm for the global prefix. New npm exposes `npm prefix -g`; older
 * versions answer the same question via `npm config get prefix`. We try the
 * modern form first and fall back to the legacy one so older Node
 * distributions bundled with older npm still work.
 */
async function getGlobalPrefix(
  execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>,
): Promise<string | null> {
  const modern = await execCapture("npm", ["prefix", "-g"]);
  if (modern.exitCode === 0) {
    const value = modern.stdout.trim();
    if (value) return value;
  }
  const legacy = await execCapture("npm", ["config", "get", "prefix"]);
  if (legacy.exitCode === 0) {
    const value = legacy.stdout.trim();
    if (value) return value;
  }
  return null;
}

/** Strip trailing slashes and resolve the bin subdir of an npm prefix. */
function globalBinDir(prefix: string): string {
  const trimmed = prefix.replace(/\/+$/, "");
  return `${trimmed}/bin`;
}

/**
 * True when `child` is at or under `parent`. Both arguments are expected to be
 * absolute, POSIX-style paths. We refuse to match `/foo` against `/foobar`.
 */
function pathStartsWith(child: string, parent: string): boolean {
  if (child === parent) return true;
  if (!child.startsWith(parent)) return false;
  const next = child.charAt(parent.length);
  return next === "/" || next === "";
}

export async function selfUpdate(opts: SelfUpdateOptions = {}): Promise<SelfUpdateResult> {
  const logger = opts.logger ?? defaultLogger;
  const which = opts.deps?.which ?? defaultWhich;
  const execCapture = opts.deps?.execCapture ?? defaultExecCapture;

  if (opts.noSelf === true || process.env.PISQUAD_NO_SELF === "1") {
    return { updated: false, reason: "--no-self or PISQUAD_NO_SELF=1" };
  }

  const currentPath = which("pisquad");
  if (!currentPath) {
    logger.info("CLI not on PATH, skipping self-update");
    return { updated: false, reason: "pisquad not on PATH" };
  }

  const globalPrefix = await getGlobalPrefix(execCapture);
  if (!globalPrefix) {
    logger.warn("Unable to determine npm global prefix, skipping self-update");
    return { updated: false, reason: "npm prefix detection failed" };
  }

  const binDir = globalBinDir(globalPrefix);
  if (!pathStartsWith(currentPath, binDir)) {
    logger.info("CLI not from global npm, skipping self-update");
    return { updated: false, reason: `not under npm global bin (${binDir})` };
  }

  // Confirmed global install — but only re-run `npm install -g` when the
  // registry actually has a newer version. An unconditional reinstall always
  // exits 0 (npm considers itself "up to date"), which previously made
  // `selfUpdate` return `updated: true` on every run and forced the user
  // into a `pisquad upgrade → re-run → upgrade → re-run` loop. We compare
  // the installed version (from this CLI's package.json) to the registry
  // version (`npm view`) and short-circuit when they match.
  const currentVersion = readCliVersion();
  const latestVersion = await getLatestVersion(execCapture);
  if (latestVersion === null) {
    logger.warn("Could not check latest pisquad version on registry, skipping self-update");
    return { updated: false, reason: "npm view failed" };
  }
  if (latestVersion === currentVersion) {
    logger.info(`pisquad is already up to date (v${currentVersion})`);
    return { updated: false, reason: "already latest" };
  }
  logger.info(`Updating pisquad v${currentVersion} → v${latestVersion}`);
  logger.info(`Updating pisquad via npm install -g (timeout ${NPM_TIMEOUT_MS / 1000}s)`);
  let result: ExecCaptureResult;
  try {
    result = await (opts.deps?.runNpmInstallGlobal ?? runNpmInstallGlobal)();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`self-update failed: ${message}`);
  }

  if (result.exitCode !== 0) {
    const combined = (result.stderr || result.stdout || "").trim();
    const snippet = combined.length > 800 ? `${combined.slice(0, 800)}…` : combined;
    throw new Error(
      `npm install -g @nicklin/pisquad@latest exited ${result.exitCode}${snippet ? `\n${snippet}` : ""}`,
    );
  }

  return { updated: true };
}

import { createHash } from "node:crypto";
import { createReadStream, lstatSync, readdirSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { resolveAsset } from "./paths.js";

/** Map of relative path (POSIX-style, forward slashes) → lowercase hex sha256. */
export interface FileHashMap {
  [relPath: string]: string;
}

export interface Sha256DirOptions {
  /** Return true to skip a relative path. Applied recursively inside the tree. */
  ignore?: (relPath: string) => boolean;
}

/**
 * Pair one subtree inside the pisquad package with the matching subtree inside
 * the install target. The two subtrees are walked independently and their
 * relative paths are merged into one logical tree for diffing.
 *
 * IMPORTANT: the caller MUST include the `docs` subtree
 * (`{ pkgSubPath: "docs", targetSubPath: "docs" }`) — see PRD §6 "upgrade 安
 * 全机制": docs is the most frequently consumer-edited area and must be
 * diffed alongside `.pi` so the upgrader can detect user modifications and
 * back them up.
 */
export interface PkgInclude {
  /** Subtree under the package's `assets/` directory, e.g. ".pi" or "docs". */
  pkgSubPath: string;
  /** Matching subtree inside the install target, e.g. ".pi" or "docs". */
  targetSubPath: string;
}

export interface DiffTreeOptions {
  /** Skip a relative path on BOTH sides. Defaults to `defaultIgnore`. */
  ignore?: (relPath: string) => boolean;
  /**
   * Override the directory pkg subpaths are resolved against. Defaults to
   * `resolveAsset` (i.e. `<package root>/assets`). Tests use this to point at
   * a synthetic assets tree without mutating the shipped assets.
   */
  assetsRoot?: string;
}

export interface DiffPlan {
  /** Present in both, hash differs — back up then overwrite. */
  modified: Array<{ relPath: string; fromHash: string; toHash: string }>;
  /** Only in pkg — copy into target (no backup needed). */
  added: Array<{ relPath: string; toHash: string }>;
  /** Only in target — kept by default; only deleted when `--prune` is passed. */
  removed: Array<{ relPath: string; fromHash: string }>;
  /** Present in both, same hash — informational. */
  unchanged: Array<{ relPath: string }>;
}

/**
 * Runtime / tool-generated entries that do not count as "user modifications"
 * and are therefore excluded from the diff on both sides:
 *
 * - `node_modules/` — restored by `npm install` after every channel copy
 * - `.pisquad/` — pisquad's own state.json + backups
 * - `.codegraph/` — codegraph CLI's tool-generated cache
 * - `.entire/` — entire CLI's tool-generated metadata
 * - `.DS_Store` — macOS Finder debris
 */
export const DEFAULT_IGNORE_NAMES = new Set([
  "node_modules",
  ".pisquad",
  ".codegraph",
  ".entire",
  ".DS_Store",
]);

/** Default ignore predicate: true for any path whose any segment is in DEFAULT_IGNORE_NAMES. */
export function defaultIgnore(relPath: string): boolean {
  return relPath.split("/").some((segment) => DEFAULT_IGNORE_NAMES.has(segment));
}

/** Compute the sha256 of a single file as lowercase hex. */
export function sha256File(path: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = createHash("sha256");
    const stream = createReadStream(path);
    stream.on("error", reject);
    stream.on("data", (chunk: Buffer | string) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

/**
 * Recursively hash every regular file under `root`. Returns a map keyed by
 * POSIX-style relative paths from `root`. Symlinks are skipped (not followed)
 * to match the conservative behaviour of `copy.ts`.
 */
export async function sha256Dir(root: string, opts: Sha256DirOptions = {}): Promise<FileHashMap> {
  const result: FileHashMap = {};

  const walk = async (dir: string): Promise<void> => {
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      // Missing directory → empty contribution. Lets `diffTree` treat the
      // other side as the authoritative source of entries.
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      const stat = lstatSync(full);
      // Symlinks are skipped for parity with copy.ts: following them could
      // escape the source tree or surface targets the caller never meant to
      // ship. The asset tree has no symlinks today, but upgrade diffs walk
      // user trees where symlinks are real.
      if (stat.isSymbolicLink()) continue;

      const rel = relative(root, full).split(sep).join("/");
      if (opts.ignore?.(rel)) continue;

      if (stat.isDirectory()) {
        await walk(full);
      } else if (stat.isFile()) {
        result[rel] = await sha256File(full);
      }
      // Other entry types (sockets, devices, fifos) are silently ignored — they
      // have no place in a sha256 diff.
    }
  };

  await walk(root);
  return result;
}

/**
 * Compare the package's payload subtrees against the matching subtrees in the
 * install target.
 *
 * The returned `modified` (and, if `--prune` is in play, `removed`) entries
 * use paths relative to the install target, so they can be passed straight
 * into `backup.createBackup` and `copy.copyDir` without re-mapping.
 */
export async function diffTree(
  target: string,
  pkgIncludes: PkgInclude[],
  opts: DiffTreeOptions = {},
): Promise<DiffPlan> {
  const ignore = opts.ignore ?? defaultIgnore;
  const assetsRoot = opts.assetsRoot;

  // Build fromHash (target, current install) and toHash (pkg, new version)
  // maps. Both are keyed by relPath from the matching subtree base, so as long
  // as pkgSubPath === targetSubPath the key spaces line up and the merge is
  // direct. pkgSubPath is resolved against the package's assets/ directory —
  // the same convention installCore uses (`resolveAsset`).
  const fromHash: FileHashMap = {};
  const toHash: FileHashMap = {};

  for (const inc of pkgIncludes) {
    const pkgAbs = assetsRoot ? join(assetsRoot, inc.pkgSubPath) : resolveAsset(inc.pkgSubPath);
    const targetAbs = join(target, inc.targetSubPath);
    const pkgMap = await sha256Dir(pkgAbs, { ignore });
    const targetMap = await sha256Dir(targetAbs, { ignore });
    // Re-key both maps with the targetSubPath prefix so the merged maps are
    // keyed by relPath-from-target (e.g. `docs/README.md`, `.pi/agents/a.md`).
    // That makes the plan entries directly usable by backup.createBackup and
    // copy.copyDir, which join them onto `target`.
    const prefix = inc.targetSubPath;
    for (const [rel, hash] of Object.entries(pkgMap)) {
      const key = prefix ? `${prefix}/${rel}` : rel;
      toHash[key] = hash;
    }
    for (const [rel, hash] of Object.entries(targetMap)) {
      const key = prefix ? `${prefix}/${rel}` : rel;
      fromHash[key] = hash;
    }
  }

  const plan: DiffPlan = { modified: [], added: [], removed: [], unchanged: [] };
  const seen = new Set<string>();
  for (const [rel, toHashValue] of Object.entries(toHash)) {
    seen.add(rel);
    if (!(rel in fromHash)) {
      plan.added.push({ relPath: rel, toHash: toHashValue });
    } else if (fromHash[rel] !== toHashValue) {
      plan.modified.push({ relPath: rel, fromHash: fromHash[rel], toHash: toHashValue });
    } else {
      plan.unchanged.push({ relPath: rel });
    }
  }
  for (const rel of Object.keys(fromHash)) {
    if (seen.has(rel)) continue;
    plan.removed.push({ relPath: rel, fromHash: fromHash[rel] });
  }

  // Deterministic output for tests + predictable upgrade logs.
  const byRel = (a: { relPath: string }, b: { relPath: string }): number =>
    a.relPath.localeCompare(b.relPath);
  plan.modified.sort(byRel);
  plan.added.sort(byRel);
  plan.removed.sort(byRel);
  plan.unchanged.sort(byRel);

  return plan;
}

import { existsSync, lstatSync, readdirSync, statSync, unlinkSync } from "node:fs";
import { join } from "node:path";
import { ensureDir } from "./fs-safe.js";
import { execCapture, which } from "./env.js";

/** A file targeted for backup. `relPath` is relative to the install target. */
export interface BackupEntry {
  relPath: string;
}

export interface BackupResult {
  path: string;
  fileCount: number;
  bytes: number;
}

export interface BackupInfo {
  path: string;
  fileName: string;
  /** ISO timestamp embedded in the file name (no `:` or `.`), e.g. `20260115T103045Z`. */
  iso: string;
  label: string;
  bytes: number;
  modifiedAt: Date;
}

const FILE_NAME_RE = /^(\d{8}T\d{6}Z)-(.+)\.tar\.gz$/;

/** Directory under which upgrade-time backups are stored. */
export function backupDir(target: string): string {
  return join(target, ".pi", ".pisquad", "backups");
}

/**
 * Build the iso timestamp suffix used in backup file names per
 * `docs/conventions/install-state.md`: ISO 8601 with `:` and `.` stripped
 * (e.g. `2026-01-15T10:30:45.123Z` → `20260115T103045Z`).
 */
export function isoStamp(date: Date = new Date()): string {
  return date.toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
}

/**
 * Reduce a caller-supplied label to a tar-safe form. Spaces, slashes, control
 * characters and shell metacharacters are collapsed into `-`; leading/trailing
 * dashes are trimmed. Empty results are rejected.
 */
export function sanitizeLabel(label: string): string {
  const sanitized = label.trim().replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "");
  if (!sanitized) {
    throw new Error(`backup: invalid label ${JSON.stringify(label)}`);
  }
  return sanitized;
}

/**
 * Tar up the listed files into
 * `<target>/.pi/.pisquad/backups/<iso>-<label>.tar.gz`. Paths inside the
 * archive are relative to `target` (e.g. `docs/README.md`).
 *
 * The system `tar` CLI is required. A missing tar is a hard error: backup is
 * the upgrader's safety net, so silently degrading it would defeat PRD §6.
 * If we ever need stronger cross-platform guarantees we can swap in the
 * `tar` npm package here.
 */
export async function createBackup(
  target: string,
  files: BackupEntry[],
  label: string,
): Promise<BackupResult> {
  if (files.length === 0) {
    throw new Error("createBackup: no files to back up");
  }
  if (which("tar") === null) {
    throw new Error(
      "createBackup: system 'tar' command not found on PATH — backups require tar to safely archive user changes",
    );
  }

  const safeLabel = sanitizeLabel(label);
  const dir = backupDir(target);
  ensureDir(dir);

  const stamp = isoStamp();
  const fileName = `${stamp}-${safeLabel}.tar.gz`;
  const out = join(dir, fileName);

  // Validate every file exists and is a regular file. A backup that quietly
  // drops a file is worse than no backup: the upgrader would overwrite a
  // file that was never archived.
  const rels: string[] = [];
  for (const f of files) {
    const abs = join(target, f.relPath);
    if (!existsSync(abs)) {
      throw new Error(`createBackup: file does not exist: ${f.relPath}`);
    }
    const stat = lstatSync(abs);
    if (!stat.isFile()) {
      throw new Error(`createBackup: not a regular file: ${f.relPath}`);
    }
    rels.push(f.relPath);
  }

  const result = await execCapture("tar", ["-czf", out, "-C", target, ...rels]);
  if (result.exitCode !== 0) {
    throw new Error(
      `createBackup: tar exited ${result.exitCode}\nstderr: ${result.stderr.trim()}`,
    );
  }

  const stat = statSync(out);
  console.log(`Backed up ${files.length} files → ${out}`);
  return { path: out, fileCount: files.length, bytes: stat.size };
}

/** List existing backups in ascending iso-timestamp order. Non-matching files are ignored. */
export function listBackups(target: string): BackupInfo[] {
  const dir = backupDir(target);
  if (!existsSync(dir)) return [];
  const out: BackupInfo[] = [];
  for (const name of readdirSync(dir)) {
    const match = FILE_NAME_RE.exec(name);
    if (!match) continue;
    const [, iso, label] = match;
    const path = join(dir, name);
    const stat = statSync(path);
    out.push({ path, fileName: name, iso, label, bytes: stat.size, modifiedAt: stat.mtime });
  }
  out.sort((a, b) => a.iso.localeCompare(b.iso));
  return out;
}

/**
 * Delete backups whose iso timestamp is strictly before `before`. Returns the
 * number of files pruned. Intentionally not auto-invoked by upgrade — reserved
 * for the future `pisquad restore` workflow.
 */
export function pruneBackup(target: string, before: Date): number {
  const beforeIso = isoStamp(before);
  let pruned = 0;
  for (const b of listBackups(target)) {
    if (b.iso >= beforeIso) continue;
    try {
      unlinkSync(b.path);
      pruned++;
    } catch {
      // Best-effort: leave unremovable files for the user to inspect.
    }
  }
  return pruned;
}

# 交互式 `pisquad upgrade` — 实施计划

